CREATE TABLE IF NOT EXISTS assets (key TEXT PRIMARY KEY, tier TEXT NOT NULL CHECK (tier IN ('public','company')), type TEXT NOT NULL, size INTEGER NOT NULL, updated INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS logs (id INTEGER PRIMARY KEY AUTOINCREMENT, at INTEGER NOT NULL, tool TEXT NOT NULL, code TEXT NOT NULL, ver TEXT, ua TEXT);
CREATE INDEX IF NOT EXISTS logs_at ON logs(at);
CREATE TABLE IF NOT EXISTS fb_pages (id TEXT PRIMARY KEY, short TEXT NOT NULL, utm TEXT NOT NULL DEFAULT '', utm_text TEXT NOT NULL DEFAULT '', rd TEXT NOT NULL DEFAULT '', ord INTEGER NOT NULL DEFAULT 999, show INTEGER NOT NULL DEFAULT 1, updated INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS fb_presets (ord INTEGER PRIMARY KEY, name TEXT NOT NULL, body TEXT NOT NULL, updated INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS fb_settings (k TEXT PRIMARY KEY, v TEXT NOT NULL, updated INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS staff_groups (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE, perms TEXT NOT NULL, ord INTEGER NOT NULL DEFAULT 0, updated INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS staff (id TEXT PRIMARY KEY, name TEXT NOT NULL, grp INTEGER NOT NULL, contact TEXT NOT NULL DEFAULT '', enabled INTEGER NOT NULL DEFAULT 1, created INTEGER NOT NULL, updated INTEGER NOT NULL, last_login INTEGER);
CREATE TABLE IF NOT EXISTS fb_audit (id INTEGER PRIMARY KEY AUTOINCREMENT, at INTEGER NOT NULL, uid TEXT NOT NULL, name TEXT NOT NULL, action TEXT NOT NULL, page TEXT NOT NULL DEFAULT '', post TEXT NOT NULL DEFAULT '', detail TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS fb_audit_at ON fb_audit(at);
